/** 宁津县中心坐标 [lat, lng] */
export const NINGJIN_CENTER: [number, number] = [37.655, 116.805];
export const NINGJIN_ZOOM = 12;

// ─── 乡镇中心坐标（从 GeoJSON 多边形质心计算）──────────────
/** 各乡镇几何中心 [lng, lat]，用于无 GPS 坐标时的回退定位 */
export const TOWNSHIP_CENTERS: Record<string, [number, number]> = {
  '刘营伍乡': [116.7665, 37.7475],
  '张大庄镇': [116.7984, 37.8012],
  '柴胡店镇': [116.9276, 37.6317],
  '大曹镇': [116.5892, 37.5754],
  '保店镇': [116.6868, 37.6202],
  '长官镇': [116.8925, 37.8117],
  '大柳镇': [116.8594, 37.7522],
  '时集镇': [116.7656, 37.6965],
  '杜集镇': [116.9341, 37.7143],
  '相衙镇': [116.6892, 37.6901],
  '宁城街道': [116.7949, 37.6347],
  '津城街道': [116.8030, 37.6232],
};

/** 全部乡镇名称列表（按 TOWNSHIP_CENTERS 顺序，用于确定性分配） */
export const TOWNSHIP_NAMES = Object.keys(TOWNSHIP_CENTERS);

/**
 * 为没有 GPS 坐标的风险点生成回退坐标
 *
 * 策略：
 *   - 若 location 文本匹配到某乡镇名 → 用该乡镇中心 + ID 偏移
 *   - 否则 → 按 ID 确定性哈希分配到某个乡镇中心 + 微小抖动
 *   - 保证同一记录每次调用返回相同坐标（确定性）
 *
 * @param record 风险点记录
 * @returns [lng, lat] 或 null（不应返回 null）
 */
export function getFallbackCoords(record: { id?: number; name?: string; location?: string; sheet?: string }): [number, number] | null {
  const townNames = TOWNSHIP_NAMES;
  const id = record.id ?? 0;
  const text = `${record.name || ''} ${record.location || ''} ${record.sheet || ''}`;

  // 1) 尝试从 location/sheet 文本中模糊匹配乡镇名
  for (const town of townNames) {
    if (text.includes(town)) {
      const center = TOWNSHIP_CENTERS[town];
      return jitter(center!, id);
    }
  }

  // 2) 按 ID 确定性分配到各乡镇（均匀分布）
  const idx = id % townNames.length;
  const center = TOWNSHIP_CENTERS[townNames[idx]!];
  return jitter(center!, id);
}

/** 在中心坐标附近添加微小偏移（基于 ID 的确定性伪随机） */
function jitter(center: [number, number], seed: number): [number, number] {
  // 简单的确定性伪随机：用 seed 生成 [-0.008, +0.008] 度的偏移（约 ±800m）
  const a = Math.sin(seed * 1234.5678) * 0.008;
  const b = Math.cos(seed * 8765.4321) * 0.008;
  return [center[0] + a, center[1] + b];
}
